{
  "manifest_version": 3,
  "name": "FigJam to Markdown",
  "version": "0.1.0",
  "description": "Copy FigJam boards and selections as Markdown.",
  "action": {
    "default_title": "Copy FigJam as Markdown",
    "default_icon": {
      "16": "icons/icon-16.png",
      "32": "icons/icon-32.png",
      "48": "icons/icon-48.png",
      "128": "icons/icon-128.png"
    }
  },
  "icons": {
    "16": "icons/icon-16.png",
    "32": "icons/icon-32.png",
    "48": "icons/icon-48.png",
    "128": "icons/icon-128.png"
  },
  "permissions": ["activeTab", "scripting"],
  "host_permissions": ["https://www.figma.com/*", "https://figma.com/*"],
  "background": {
    "service_worker": "background.js",
    "type": "module"
  },
  "content_scripts": [
    {
      "matches": ["https://www.figma.com/*", "https://figma.com/*"],
      "js": ["content.js"],
      "run_at": "document_idle"
    }
  ],
  "web_accessible_resources": [
    {
      "resources": ["figma-bridge.js"],
      "matches": ["https://www.figma.com/*", "https://figma.com/*"]
    }
  ]
}

const FIGMA_HOSTS = new Set(["www.figma.com", "figma.com"]);

chrome.action.onClicked.addListener(async (tab) => {
  if (!tab.id || !tab.url) {
    return;
  }

  const url = new URL(tab.url);
  if (!FIGMA_HOSTS.has(url.hostname)) {
    await chrome.tabs.create({ url: "https://www.figma.com/figjam/" });
    return;
  }

  try {
    await chrome.tabs.sendMessage(tab.id, { type: "FIGJAM2MD_TOGGLE" });
  } catch {
    await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      files: ["content.js"],
    });
    await chrome.tabs.sendMessage(tab.id, { type: "FIGJAM2MD_TOGGLE" });
  }
});

