declare global {
  interface Window {
    __figjam2mdContentLoaded?: boolean;
  }
}

type BridgeResponse = {
  source: "figjam2md-bridge";
  type: "FIGJAM2MD_RESPONSE";
  id: string;
  ok: boolean;
  markdown?: string;
  itemCount?: number;
  scope?: "selection" | "page";
  pageName?: string;
  error?: string;
};

type MarkdownResult = {
  markdown: string;
  itemCount: number;
  scope: "selection" | "page";
  pageName?: string;
};

if (!window.__figjam2mdContentLoaded) {
  window.__figjam2mdContentLoaded = true;

  const APP_ID = "figjam2md-dialog-root";
  const BRIDGE_ID = "figjam2md-bridge-script";

  let host: HTMLDivElement | null = null;
  let shadow: ShadowRoot | null = null;
  let textarea: HTMLTextAreaElement | null = null;
  let status: HTMLDivElement | null = null;
  let copyButton: HTMLButtonElement | null = null;

  chrome.runtime.onMessage.addListener((message) => {
    if (message?.type === "FIGJAM2MD_TOGGLE") {
      void toggleDialog();
    }
  });

  async function toggleDialog() {
    if (host?.isConnected) {
      host.remove();
      host = null;
      shadow = null;
      textarea = null;
      status = null;
      copyButton = null;
      return;
    }

    ensureBridgeScript();
    renderDialog();
    await refreshMarkdown();
  }

  function ensureBridgeScript() {
    if (document.getElementById(BRIDGE_ID)) {
      return;
    }

    const script = document.createElement("script");
    script.id = BRIDGE_ID;
    script.src = chrome.runtime.getURL("figma-bridge.js");
    script.async = false;
    (document.head || document.documentElement).append(script);
  }

  function renderDialog() {
    host = document.createElement("div");
    host.id = APP_ID;
    shadow = host.attachShadow({ mode: "open" });

    const style = document.createElement("style");
    style.textContent = `
      :host {
        all: initial;
        color-scheme: light dark;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }

      .panel {
        position: fixed;
        top: 20px;
        right: 20px;
        width: min(420px, calc(100vw - 40px));
        max-height: calc(100vh - 40px);
        z-index: 2147483647;
        display: flex;
        flex-direction: column;
        overflow: hidden;
        border: 1px solid rgba(0, 0, 0, 0.14);
        border-radius: 14px;
        background: #fff;
        box-shadow: 0 16px 48px rgba(0, 0, 0, 0.24);
        color: #171717;
      }

      .header,
      .footer {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 12px;
      }

      .header {
        border-bottom: 1px solid rgba(0, 0, 0, 0.08);
      }

      .title {
        flex: 1;
        font-size: 14px;
        font-weight: 700;
      }

      .status {
        min-height: 18px;
        padding: 8px 12px 0;
        color: #666;
        font-size: 12px;
        line-height: 1.4;
      }

      textarea {
        box-sizing: border-box;
        width: calc(100% - 24px);
        min-height: 240px;
        margin: 8px 12px 0;
        resize: vertical;
        border: 1px solid rgba(0, 0, 0, 0.14);
        border-radius: 10px;
        padding: 10px;
        background: #fafafa;
        color: #171717;
        font: 12px/1.45 ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
      }

      .footer {
        justify-content: flex-end;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 8px 12px;
        background: #f0f0f0;
        color: #171717;
        cursor: pointer;
        font: 600 12px/1 Inter, ui-sans-serif, system-ui, sans-serif;
      }

      button:hover:not(:disabled) {
        background: #e4e4e4;
      }

      button:disabled {
        cursor: not-allowed;
        opacity: 0.5;
      }

      .primary {
        background: #18a0fb;
        color: white;
      }

      .primary:hover:not(:disabled) {
        background: #0d8de3;
      }

      .icon-button {
        width: 30px;
        height: 30px;
        padding: 0;
        border-radius: 50%;
        font-size: 16px;
      }

      .error {
        color: #b42318;
      }

      @media (prefers-color-scheme: dark) {
        .panel {
          border-color: rgba(255, 255, 255, 0.16);
          background: #242424;
          color: #f5f5f5;
        }

        .header {
          border-bottom-color: rgba(255, 255, 255, 0.1);
        }

        .status {
          color: #bdbdbd;
        }

        textarea {
          border-color: rgba(255, 255, 255, 0.16);
          background: #1b1b1b;
          color: #f5f5f5;
        }

        button {
          background: #3a3a3a;
          color: #f5f5f5;
        }

        button:hover:not(:disabled) {
          background: #474747;
        }

        .primary,
        .primary:hover:not(:disabled) {
          background: #18a0fb;
          color: white;
        }
      }
    `;

    const panel = document.createElement("section");
    panel.className = "panel";
    panel.innerHTML = `
      <div class="header">
        <div class="title">FigJam → Markdown</div>
        <button class="icon-button" data-action="refresh" title="Refresh Markdown" type="button">↻</button>
        <button class="icon-button" data-action="close" title="Close" type="button">×</button>
      </div>
      <div class="status">Loading FigJam content…</div>
      <textarea spellcheck="false" aria-label="FigJam Markdown"></textarea>
      <div class="footer">
        <button data-action="refresh" type="button">Refresh</button>
        <button class="primary" data-action="copy" type="button" disabled>Copy as Markdown</button>
      </div>
    `;

    shadow.append(style, panel);
    document.documentElement.append(host);

    textarea = shadow.querySelector("textarea");
    status = shadow.querySelector(".status");
    copyButton = shadow.querySelector('[data-action="copy"]');

    shadow.addEventListener("click", (event) => {
      const target = event.target;
      if (!(target instanceof HTMLElement)) {
        return;
      }

      const action = target.dataset.action;
      if (action === "close") {
        host?.remove();
      } else if (action === "refresh") {
        void refreshMarkdown();
      } else if (action === "copy") {
        void copyMarkdown();
      }
    });
  }

  async function refreshMarkdown() {
    setStatus("Loading FigJam content…");
    if (copyButton) copyButton.disabled = true;
    if (textarea) textarea.value = "";

    try {
      const result = await requestMarkdown();
      if (textarea) textarea.value = result.markdown;
      if (copyButton) copyButton.disabled = result.markdown.trim().length === 0;

      const source = result.scope === "selection" ? "selected item" : "page item";
      const plural = result.itemCount === 1 ? source : `${source}s`;
      const page = result.pageName ? ` from “${result.pageName}”` : "";
      setStatus(`Ready: ${result.itemCount} ${plural}${page}.`);
    } catch (error) {
      const message = error instanceof Error ? error.message : "Unable to read FigJam content.";
      setStatus(message, true);
      if (textarea) textarea.value = "";
    }
  }

  function requestMarkdown(): Promise<MarkdownResult> {
    const id = `${Date.now()}-${Math.random().toString(36).slice(2)}`;

    return new Promise((resolve, reject) => {
      const timeout = window.setTimeout(() => {
        window.removeEventListener("message", onMessage);
        reject(new Error("Timed out reading FigJam. Reload the FigJam file and try again."));
      }, 5000);

      function onMessage(event: MessageEvent<unknown>) {
        if (event.source !== window || !isBridgeResponse(event.data) || event.data.id !== id) {
          return;
        }

        window.clearTimeout(timeout);
        window.removeEventListener("message", onMessage);

        if (!event.data.ok) {
          reject(new Error(event.data.error || "Unable to read FigJam content."));
          return;
        }

        resolve({
          markdown: event.data.markdown || "",
          itemCount: event.data.itemCount || 0,
          scope: event.data.scope || "page",
          pageName: event.data.pageName,
        });
      }

      window.addEventListener("message", onMessage);
      window.postMessage({ source: "figjam2md-content", type: "FIGJAM2MD_REQUEST", id }, "*");
    });
  }

  function isBridgeResponse(value: unknown): value is BridgeResponse {
    return (
      typeof value === "object" &&
      value !== null &&
      (value as BridgeResponse).source === "figjam2md-bridge" &&
      (value as BridgeResponse).type === "FIGJAM2MD_RESPONSE" &&
      typeof (value as BridgeResponse).id === "string"
    );
  }

  async function copyMarkdown() {
    const markdown = textarea?.value || "";
    if (!markdown.trim()) {
      return;
    }

    try {
      await navigator.clipboard.writeText(markdown);
      setStatus("Copied Markdown to clipboard.");
    } catch {
      fallbackCopy(markdown);
      setStatus("Copied Markdown to clipboard.");
    }
  }

  function fallbackCopy(text: string) {
    const copyArea = document.createElement("textarea");
    copyArea.value = text;
    copyArea.style.position = "fixed";
    copyArea.style.left = "-9999px";
    document.body.append(copyArea);
    copyArea.focus();
    copyArea.select();
    document.execCommand("copy");
    copyArea.remove();
  }

  function setStatus(message: string, isError = false) {
    if (!status) {
      return;
    }

    status.textContent = message;
    status.classList.toggle("error", isError);
  }
}

