declare global {
  interface Window {
    figma?: unknown;
    __figjam2mdBridgeLoaded?: boolean;
  }
}

type FigmaLike = {
  editorType?: string;
  currentPage?: FigJamNode;
};

type FigJamNode = {
  id?: string;
  name?: string;
  type?: string;
  visible?: boolean;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  absoluteBoundingBox?: { x?: number; y?: number; width?: number; height?: number };
  children?: unknown;
  selection?: unknown;
  characters?: unknown;
  text?: unknown;
  numRows?: unknown;
  numColumns?: unknown;
  cellAt?: unknown;
  getRangeAllFontNames?: unknown;
};

type ContentRequest = {
  source?: string;
  type?: string;
  id?: string;
};

type MarkdownDocument = {
  markdown: string;
  itemCount: number;
  scope: "selection" | "page";
  pageName?: string;
};

if (!window.__figjam2mdBridgeLoaded) {
  window.__figjam2mdBridgeLoaded = true;

  window.addEventListener("message", (event: MessageEvent<unknown>) => {
    if (event.source !== window || !isContentRequest(event.data)) {
      return;
    }

    try {
      const result = readFigJamAsMarkdown();
      window.postMessage(
        {
          source: "figjam2md-bridge",
          type: "FIGJAM2MD_RESPONSE",
          id: event.data.id,
          ok: true,
          ...result,
        },
        "*",
      );
    } catch (error) {
      window.postMessage(
        {
          source: "figjam2md-bridge",
          type: "FIGJAM2MD_RESPONSE",
          id: event.data.id,
          ok: false,
          error: error instanceof Error ? error.message : "Unable to read FigJam content.",
        },
        "*",
      );
    }
  });
}

function isContentRequest(value: unknown): value is Required<ContentRequest> {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as ContentRequest).source === "figjam2md-content" &&
    (value as ContentRequest).type === "FIGJAM2MD_REQUEST" &&
    typeof (value as ContentRequest).id === "string"
  );
}

function readFigJamAsMarkdown(): MarkdownDocument {
  const figma = window.figma as FigmaLike | undefined;
  if (!figma) {
    throw new Error('window.figma is not available on this page. Open a FigJam file and try again.');
  }

  if (figma.editorType && figma.editorType !== "figjam") {
    throw new Error("This extension only reads FigJam files. Open a FigJam board and try again.");
  }

  const page = figma.currentPage;
  if (!page) {
    throw new Error("No active FigJam page was found.");
  }

  const selection = arrayFromNodes(page.selection).filter(isVisibleNode);
  const scope: "selection" | "page" = selection.length > 0 ? "selection" : "page";
  const roots = (selection.length > 0 ? selection : arrayFromNodes(page.children).filter(isVisibleNode)).sort(comparePosition);

  const seen = new WeakSet<object>();
  const blocks = roots.map((node) => nodeToMarkdown(node, 2, seen)).filter(Boolean);

  const pageName = cleanText(page.name || "");
  const title = scope === "page" && pageName ? heading(pageName, 1) : "";
  const markdown = joinBlocks([title, ...blocks]);

  return {
    markdown,
    itemCount: roots.length,
    scope,
    ...(pageName ? { pageName } : {}),
  };
}

function nodeToMarkdown(node: FigJamNode, depth: number, seen: WeakSet<object>): string {
  if (!isObject(node) || seen.has(node) || !isVisibleNode(node)) {
    return "";
  }
  seen.add(node);

  const type = String(node.type || "").toUpperCase();
  const label = readableName(node);
  const text = extractNodeText(node);
  const children = childBlocks(node, depth + 1, seen);

  if (type === "TABLE") {
    const table = tableToMarkdown(node);
    return table || joinBlocks(children);
  }

  if (type === "SECTION" || type === "FRAME") {
    return joinBlocks([label ? heading(label, depth) : "", ...children]);
  }

  if (type === "GROUP") {
    return joinBlocks([label && children.length > 0 ? heading(label, depth) : "", text, ...children]);
  }

  if (type === "CODE_BLOCK") {
    return text ? fencedCode(text, node) : joinBlocks(children);
  }

  if (type === "CONNECTOR") {
    return text ? text : label;
  }

  if (text && label && label !== text && shouldShowLabel(node)) {
    return joinBlocks([bold(label), text, ...children]);
  }

  return joinBlocks([text || (shouldShowLabel(node) ? label : ""), ...children]);
}

function childBlocks(node: FigJamNode, depth: number, seen: WeakSet<object>): string[] {
  return arrayFromNodes(node.children)
    .filter(isVisibleNode)
    .sort(comparePosition)
    .map((child) => nodeToMarkdown(child, depth, seen))
    .filter(Boolean);
}

function extractNodeText(node: FigJamNode): string {
  const directText = firstText([
    node.characters,
    node.text,
    property(node, "plainText"),
    property(node, "content"),
    property(node, "contents"),
    property(node, "value"),
  ]);

  return cleanText(directText);
}

function firstText(values: unknown[]): string {
  for (const value of values) {
    const text = textFromValue(value, new WeakSet<object>());
    if (text.trim()) {
      return text;
    }
  }
  return "";
}

function textFromValue(value: unknown, seen: WeakSet<object>): string {
  if (typeof value === "string") {
    return value;
  }

  if (!isObject(value) || seen.has(value)) {
    return "";
  }
  seen.add(value);

  const keys = ["characters", "text", "plainText", "content", "contents", "value", "label"];
  for (const key of keys) {
    const nested = textFromValue(property(value, key), seen);
    if (nested.trim()) {
      return nested;
    }
  }

  if (Array.isArray(value)) {
    return value.map((item) => textFromValue(item, seen)).filter(Boolean).join("\n");
  }

  return "";
}

function tableToMarkdown(node: FigJamNode): string {
  const rows = toInteger(node.numRows ?? property(node, "rowCount") ?? property(node, "rows"));
  const columns = toInteger(node.numColumns ?? property(node, "columnCount") ?? property(node, "columns"));

  if (rows <= 0 || columns <= 0) {
    return "";
  }

  const matrix: string[][] = [];
  for (let row = 0; row < rows; row += 1) {
    const cells: string[] = [];
    for (let column = 0; column < columns; column += 1) {
      cells.push(escapeTableCell(readTableCell(node, row, column)));
    }
    matrix.push(cells);
  }

  if (matrix.every((row) => row.every((cell) => !cell.trim()))) {
    return "";
  }

  const header = matrix[0] || [];
  const separator = header.map(() => "---");
  const body = matrix.slice(1);

  return [header, separator, ...body].map((row) => `| ${row.join(" | ")} |`).join("\n");
}

function readTableCell(node: FigJamNode, row: number, column: number): string {
  if (typeof node.cellAt === "function") {
    try {
      return extractNodeText(node.cellAt(row, column));
    } catch {
      return "";
    }
  }

  const cells = arrayFromNodes(node.children);
  const match = cells.find((cell) => {
    const rowIndex = toInteger(property(cell, "rowIndex") ?? property(cell, "row"));
    const columnIndex = toInteger(property(cell, "columnIndex") ?? property(cell, "column"));
    return rowIndex === row && columnIndex === column;
  });

  return match ? extractNodeText(match) : "";
}

function arrayFromNodes(value: unknown): FigJamNode[] {
  if (!value) {
    return [];
  }

  if (Array.isArray(value)) {
    return value.filter(isObject) as FigJamNode[];
  }

  if (typeof (value as { [Symbol.iterator]?: unknown })[Symbol.iterator] === "function") {
    return Array.from(value as Iterable<unknown>).filter(isObject) as FigJamNode[];
  }

  return [];
}

function comparePosition(a: FigJamNode, b: FigJamNode): number {
  const ay = positionY(a);
  const by = positionY(b);
  if (Math.abs(ay - by) > 24) {
    return ay - by;
  }
  return positionX(a) - positionX(b);
}

function positionX(node: FigJamNode): number {
  return toNumber(node.absoluteBoundingBox?.x ?? node.x);
}

function positionY(node: FigJamNode): number {
  return toNumber(node.absoluteBoundingBox?.y ?? node.y);
}

function isVisibleNode(node: FigJamNode): boolean {
  return node.visible !== false;
}

function readableName(node: FigJamNode): string {
  return cleanText(node.name || "");
}

function shouldShowLabel(node: FigJamNode): boolean {
  const name = readableName(node);
  if (!name) {
    return false;
  }

  const type = String(node.type || "").toLowerCase();
  const normalized = name.toLowerCase();
  const generic = new Set([
    "connector",
    "frame",
    "group",
    "section",
    "shape",
    "shape with text",
    "sticky",
    "sticky note",
    "table",
    "text",
    type,
    type.replaceAll("_", " "),
  ]);

  return !generic.has(normalized);
}

function cleanText(value: string): string {
  return value
    .replace(/\r\n?/g, "\n")
    .replace(/\u00a0/g, " ")
    .split("\n")
    .map((line) => line.replace(/[ \t]+$/g, ""))
    .join("\n")
    .trim();
}

function heading(value: string, depth: number): string {
  const level = Math.min(Math.max(depth, 1), 6);
  return `${"#".repeat(level)} ${value.replace(/^#+\s*/, "")}`;
}

function bold(value: string): string {
  return `**${value.replaceAll("**", "") }**`;
}

function fencedCode(value: string, node: FigJamNode): string {
  const language = cleanText(String(property(node, "language") || ""));
  return `\`\`\`${language}\n${value}\n\`\`\``;
}

function joinBlocks(blocks: string[]): string {
  return blocks.map((block) => block.trim()).filter(Boolean).join("\n\n");
}

function escapeTableCell(value: string): string {
  return cleanText(value).replaceAll("|", "\\|").replace(/\n+/g, "<br>");
}

function toInteger(value: unknown): number {
  if (Array.isArray(value)) {
    return value.length;
  }
  return Math.max(0, Math.floor(toNumber(value)));
}

function toNumber(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function property(value: unknown, key: string): unknown {
  return isObject(value) ? (value as Record<string, unknown>)[key] : undefined;
}

function isObject(value: unknown): value is object {
  return typeof value === "object" && value !== null;
}

