function stickyToMarkdown(node: FigJamNode, label: string, text: string, children: string[]): string {
  const authorVisible = property(node, "authorVisible") === true;
  const author = authorVisible ? cleanText(stringProperty(node, "authorName")) : "";
  const content = author && text ? `${text}\n\n— ${author}` : text;

  if (content && label && plainMarkdown(content) !== label) {
    return joinBlocks([bold(label), content, ...children]);
  }

  return joinBlocks([content || label, ...children]);
}

function withLabel(label: string, depth: number, content: string, mode: "bold" | "heading"): string {
  if (!label) {
    return content;
  }

  return joinBlocks([mode === "heading" ? heading(label, depth) : bold(label), content]);
}

function readingOrder(nodes: FigJamNode[]): FigJamNode[] {
  if (nodes.length <= 1) {
    return nodes.slice();
  }

  const sorted = nodes.slice().sort((a, b) => positionY(a) - positionY(b) || positionX(a) - positionX(b));
  const rowTolerance = readingRowTolerance(sorted);
  const rows: FigJamNode[][] = [];

  for (const node of sorted) {
    const center = centerY(node);
    const row = rows.find((candidate) => Math.abs(averageCenterY(candidate) - center) <= rowTolerance);
    if (row) {
      row.push(node);
    } else {
      rows.push([node]);
    }
  }

  return rows.flatMap((row) => row.sort((a, b) => positionX(a) - positionX(b) || positionY(a) - positionY(b)));
}

function readingRowTolerance(nodes: FigJamNode[]): number {
  const heights = nodes.map(heightOf).filter((height) => height > 0).sort((a, b) => a - b);
  const median = heights[Math.floor(heights.length / 2)] || 48;
  return clamp(median * 0.55, 24, 120);
}

function averageCenterY(nodes: FigJamNode[]): number {
  return nodes.reduce((sum, node) => sum + centerY(node), 0) / Math.max(1, nodes.length);
}

function removeDescendants(nodes: FigJamNode[]): FigJamNode[] {
  const selected = new WeakSet<object>(nodes.filter(isObject));
  return nodes.filter((node) => !hasAncestorInSet(node, selected));
}

function hasAncestorInSet(node: FigJamNode, selected: WeakSet<object>): boolean {
  let current = property(node, "parent");
  const seen = new WeakSet<object>();

  while (isObject(current) && !seen.has(current)) {
    if (selected.has(current)) {
      return true;
    }
    seen.add(current);
    current = property(current, "parent");
  }

  return false;
}

function indexNodes(roots: FigJamNode[]): Map<string, FigJamNode> {
  const nodeById = new Map<string, FigJamNode>();
  const seen = new WeakSet<object>();
  const visit = (node: FigJamNode) => {
    if (!isObject(node) || seen.has(node)) {
      return;
    }
    seen.add(node);
    if (node.id) {
      nodeById.set(node.id, node);
    }
    for (const child of arrayFromNodes(node.children)) {
      visit(child);
    }
  };

  roots.forEach(visit);
  return nodeById;

