const FIGMA_HOSTS = new Set(["www.figma.com", "figma.com"]);
const FIGMA_READY_TIMEOUT_MS = 15000;
const FIGMA_READY_POLL_MS = 250;

type ReadResult = {
  ok: boolean;
  markdown?: string;
  itemCount?: number;
  scope?: "selection" | "page";
  pageName?: string;
  error?: string;
};

type FrameProbe = {
  href: string;
  hasFigma: boolean;
  hasCurrentPage: boolean;
  hasReader: boolean;
  editorType?: string;
  pageName?: string;
};

type ProbedFrame = FrameProbe & {
  frameId: number;
};

chrome.action.onClicked.addListener(async (tab) => {
  if (!tab.id || !tab.url) {
    return;
  }

  const url = new URL(tab.url);
  if (!FIGMA_HOSTS.has(url.hostname)) {
    await chrome.tabs.create({ url: "https://www.figma.com/figjam/" });
    return;
  }

  await ensureBridge(tab.id);

  try {
    await chrome.tabs.sendMessage(tab.id, { type: "FIGJAM2MD_TOGGLE" });
  } catch {
    await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      files: ["content.js"],
    });
    await chrome.tabs.sendMessage(tab.id, { type: "FIGJAM2MD_TOGGLE" });
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type !== "FIGJAM2MD_READ") {
    return;
  }

  const tabId = sender.tab?.id;
  if (!tabId) {
    sendResponse({ ok: false, error: "No active FigJam tab was found." } satisfies ReadResult);
    return;
  }

  void readFromAllFrames(tabId)
    .then(sendResponse)
    .catch((error) => {
      sendResponse({
        ok: false,
        error: error instanceof Error ? error.message : "Unable to inspect this FigJam tab.",
      } satisfies ReadResult);
    });
  return true;
});

async function ensureBridge(tabId: number, frameIds?: number[]) {
  try {
    await chrome.scripting.executeScript({
      target: frameIds ? { tabId, frameIds } : { tabId, allFrames: true },
      files: ["figma-bridge.js"],
      world: "MAIN",
    });
  } catch {
    // Some child frames can be restricted or transient. The probe/read path below
    // reports actionable errors for frames we can inspect.
  }
}

async function readFromAllFrames(tabId: number): Promise<ReadResult> {
  await ensureBridge(tabId);

  const candidateFrames = await waitForReadableFrames(tabId);
  if (candidateFrames.length === 0) {
    const probes = await probeFrames(tabId);
    return {
      ok: false,
      error: describeProbeFailure(probes),
    };
  }

  await ensureBridge(
    tabId,
    candidateFrames.filter((frame) => !frame.hasReader).map((frame) => frame.frameId),
  );

  const results = await chrome.scripting.executeScript({
    target: { tabId, frameIds: candidateFrames.map((frame) => frame.frameId) },
    world: "MAIN",
    func: async (): Promise<ReadResult> => {
      const reader = (window as unknown as { __figjam2mdReadFigJamAsMarkdown?: unknown }).__figjam2mdReadFigJamAsMarkdown;
      if (typeof reader !== "function") {
        return { ok: false, error: "The FigJam reader was not installed in the frame that exposes window.figma." };
      }

      try {
        const result = await reader();
        return { ok: true, ...(result as Record<string, unknown>) } as ReadResult;
      } catch (error) {
        return {
          ok: false,
          error: error instanceof Error ? error.message : "Unable to read FigJam content from this frame.",
        };
      }
    },
  });

  const frameResults = results.map((result) => result.result).filter(Boolean) as ReadResult[];
  const success = frameResults.find((result) => result.ok && typeof result.markdown === "string" && result.markdown.trim());
  if (success) {
    return success;
  }

  const errors = unique(frameResults.map((result) => result.error).filter((error): error is string => Boolean(error)));
  return {
    ok: false,
    error: errors[0] || "FigJam was found, but no readable Markdown content was returned.",
