}

async function waitForReadableFrames(tabId: number): Promise<ProbedFrame[]> {
  const startedAt = Date.now();
  let latest: ProbedFrame[] = [];

  while (Date.now() - startedAt < FIGMA_READY_TIMEOUT_MS) {
    latest = await probeFrames(tabId);
    const ready = latest.filter((frame) => frame.hasFigma && frame.hasCurrentPage);
    if (ready.length > 0) {
      return ready;
    }
    await delay(FIGMA_READY_POLL_MS);
  }

  return latest.filter((frame) => frame.hasFigma && frame.hasCurrentPage);
}

async function probeFrames(tabId: number): Promise<ProbedFrame[]> {
  try {
    const results = await chrome.scripting.executeScript({
      target: { tabId, allFrames: true },
      world: "MAIN",
      func: (): FrameProbe => {
        const figma = (window as unknown as { figma?: unknown }).figma as
          | { editorType?: unknown; currentPage?: { name?: unknown } }
          | undefined;
        const reader = (window as unknown as { __figjam2mdReadFigJamAsMarkdown?: unknown }).__figjam2mdReadFigJamAsMarkdown;

        return {
          href: window.location.href,
          hasFigma: typeof figma === "object" && figma !== null,
          hasCurrentPage: typeof figma?.currentPage === "object" && figma.currentPage !== null,
          hasReader: typeof reader === "function",
          ...(typeof figma?.editorType === "string" ? { editorType: figma.editorType } : {}),
          ...(typeof figma?.currentPage?.name === "string" ? { pageName: figma.currentPage.name } : {}),
        };
      },
    });

    return results.map((result) => ({ ...result.result, frameId: result.frameId })).filter((frame) => frame.href);
  } catch (error) {
    throw new Error(error instanceof Error ? error.message : "Chrome could not inspect the FigJam frames.");
  }
}

function describeProbeFailure(probes: ProbedFrame[]): string {
  if (probes.some((probe) => probe.hasFigma && !probe.hasCurrentPage)) {
    return "Found window.figma, but FigJam has not exposed currentPage yet. Wait until the board finishes loading, then click Refresh.";
  }

  const frameCount = probes.length;
  const inspected = frameCount === 1 ? "1 frame" : `${frameCount} frames`;
  return `window.figma was not found in any accessible FigJam frame after ${Math.round(
    FIGMA_READY_TIMEOUT_MS / 1000,
  )}s (${inspected} inspected). Reload the FigJam tab, wait for the board to finish loading, then try again.`;
}

function unique(values: string[]): string[] {
  return Array.from(new Set(values));
}

function delay(milliseconds: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

