async function waitForFigma(timeoutMs = 12000): Promise<FigmaLike> {
  const start = Date.now();

  while (Date.now() - start < timeoutMs) {
    const figma = window.figma as FigmaLike | undefined;
    if (isObject(figma) && figma.currentPage) {
      return figma;
    }
    await delay(100);
  }

  throw new Error(
    "window.figma is not available yet. Wait for the FigJam file to finish loading, then click Refresh.",
  );
}

