async function requestMarkdown(): Promise<MarkdownResult> {
  await ensurePageBridge();

  const id = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const response = await withTimeout(
    new Promise<BridgeResponse>((resolve, reject) => {
      function onMessage(event: MessageEvent<unknown>) {
        if (event.source !== window || !isBridgeResponse(event.data) || event.data.id !== id) {
          return;
        }

        window.removeEventListener("message", onMessage);
        resolve(event.data);
      }

      window.addEventListener("message", onMessage);
      window.postMessage({ source: "figjam2md-content", type: "FIGJAM2MD_REQUEST", id }, "*");

      window.setTimeout(() => {
        window.removeEventListener("message", onMessage);
        reject(new Error("The FigJam page bridge did not respond."));
      }, 12000);
    }),
    15000,
    "Timed out reading FigJam. Reload the FigJam tab, wait for the board to finish loading, then try again.",
  );

  if (!response.ok) {
    throw new Error(response.error || "Unable to read FigJam content.");
  }

  return {
    markdown: response.markdown || "",
    itemCount: response.itemCount || 0,
    scope: response.scope || "page",
    ...(response.pageName ? { pageName: response.pageName } : {}),
  };
}

function ensurePageBridge(): Promise<void> {
  const existing = document.getElementById(BRIDGE_ID) as HTMLScriptElement | null;
  if (existing?.dataset.loaded === "true") {
    return Promise.resolve();
  }

  return new Promise((resolve, reject) => {
    const script = existing || document.createElement("script");
    script.id = BRIDGE_ID;
    script.dataset.loaded = "false";
    script.src = chrome.runtime.getURL("figma-bridge.js");
    script.async = false;
    script.onload = () => {
      script.dataset.loaded = "true";
      resolve();
    };
    script.onerror = () => reject(new Error("Unable to inject the FigJam page bridge."));

    if (!existing) {
      (document.head || document.documentElement).append(script);
    }
  });
}

function isBridgeResponse(value: unknown): value is BridgeResponse {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as BridgeResponse).source === "figjam2md-bridge" &&
    (value as BridgeResponse).type === "FIGJAM2MD_RESPONSE" &&
    typeof (value as BridgeResponse).id === "string"
  );
}

