const FIGMA_HOSTS = new Set(["www.figma.com", "figma.com"]);

chrome.action.onClicked.addListener(async (tab) => {
  if (!tab.id || !tab.url) {
    return;
  }

  const url = new URL(tab.url);
  if (!FIGMA_HOSTS.has(url.hostname)) {
    await chrome.tabs.create({ url: "https://www.figma.com/figjam/" });
    return;
  }

  try {
    await chrome.tabs.sendMessage(tab.id, { type: "FIGJAM2MD_TOGGLE" });
  } catch {
    await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      files: ["content.js"],
    });
    await chrome.tabs.sendMessage(tab.id, { type: "FIGJAM2MD_TOGGLE" });
  }
});

const FIGMA_HOSTS = new Set(["www.figma.com", "figma.com"]);

type ReadResult = {
  ok: boolean;
  markdown?: string;
  itemCount?: number;
  scope?: "selection" | "page";
  pageName?: string;
  error?: string;
};

chrome.action.onClicked.addListener(async (tab) => {
  if (!tab.id || !tab.url) {
    return;
  }

  const url = new URL(tab.url);
  if (!FIGMA_HOSTS.has(url.hostname)) {
    await chrome.tabs.create({ url: "https://www.figma.com/figjam/" });
    return;
  }

  try {
    await chrome.tabs.sendMessage(tab.id, { type: "FIGJAM2MD_TOGGLE" }, { frameId: 0 });
  } catch {
    await chrome.scripting.executeScript({
      target: { tabId: tab.id, frameIds: [0] },
      files: ["content.js"],
    });
    await chrome.tabs.sendMessage(tab.id, { type: "FIGJAM2MD_TOGGLE" }, { frameId: 0 });
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type !== "FIGJAM2MD_READ") {
    return;
  }

  const tabId = sender.tab?.id;
  if (!tabId) {
    sendResponse({ ok: false, error: "No active FigJam tab was found." } satisfies ReadResult);
    return;
  }

  void readFromContentFrames(tabId)
    .then(sendResponse)
    .catch((error) => {
      sendResponse({
        ok: false,
        error: error instanceof Error ? error.message : "Unable to read FigJam content.",
      } satisfies ReadResult);
    });

  return true;
});

async function readFromContentFrames(tabId: number): Promise<ReadResult> {
  const results = await chrome.scripting.executeScript({
    target: { tabId, allFrames: true },
    func: async (): Promise<ReadResult> => {
      const reader = (window as unknown as { __figjam2mdContentFrameRead?: unknown }).__figjam2mdContentFrameRead;
      if (typeof reader !== "function") {
        return { ok: false, error: "FigJam content reader is not installed in this frame." };
      }

      try {
        const result = await reader();
        return { ok: true, ...(result as Record<string, unknown>) } as ReadResult;
      } catch (error) {
        return {
          ok: false,
          error: error instanceof Error ? error.message : "Unable to read this FigJam frame.",
        };
      }
    },
  });

  const frameResults = results.map((result) => result.result).filter(Boolean) as ReadResult[];
  const success = frameResults.find((result) => result.ok && typeof result.markdown === "string" && result.markdown.trim());
  if (success) {
    return success;
  }

  const errors = unique(frameResults.map((result) => result.error).filter((error): error is string => Boolean(error)));
  return {
    ok: false,
    error:
      errors.find((error) => !error.includes("not installed") && !error.includes("not available in this frame")) ||
      `Could not find window.figma in any extension-accessible frame (${frameResults.length} frames checked). If DevTools shows window.figma, make sure the console frame selector is set to the top FigJam document or reload the tab after reloading the extension.`,
  };
}

function unique(values: string[]): string[] {
  return Array.from(new Set(values));
}

