dist/figma-bridge.js.map:4:  "sourcesContent": ["declare global {
  interface Window {
    figma?: unknown;
    __figjam2mdBridgeLoaded?: boolean;
    __figjam2mdReadFigJamAsMarkdown?: () => Promise<MarkdownDocument>;
    __figjam2mdProbe?: () => FigJamProbe;
  }
}

type FigmaLike = {
  editorType?: string;
  currentPage?: FigJamNode;
};

type FigJamNode = {
  id?: string;
  name?: string;
  type?: string;
  visible?: boolean;
  parent?: unknown;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  absoluteBoundingBox?: Bounds;
  children?: unknown;
  selection?: unknown;
  characters?: unknown;
  text?: unknown;
  numRows?: unknown;
  numColumns?: unknown;
  cellAt?: unknown;
  loadAsync?: unknown;
};

type Bounds = {
  x?: number;
  y?: number;
  width?: number;
  height?: number;
};

type StyledTextSegmentLike = {
  characters?: unknown;
  start?: unknown;
  end?: unknown;
  fontName?: unknown;
  fontStyle?: unknown;
  fontWeight?: unknown;
  textDecoration?: unknown;
  hyperlink?: unknown;
  listOptions?: unknown;
  indentation?: unknown;
};

type TextLike = FigJamNode & {
  characters?: unknown;
  getStyledTextSegments?: unknown;
};

type ContentRequest = {
  source?: string;
  type?: string;
  id?: string;
};

type MarkdownDocument = {
  markdown: string;
  itemCount: number;
  scope: "selection" | "page";
  pageName?: string;
};

type FigJamProbe = {
  href: string;
  hasFigma: boolean;
  hasCurrentPage: boolean;
  editorType?: string;
  pageName?: string;
  selectionCount?: number;
  childCount?: number;
};

type ConversionContext = {
  nodeById: Map<string, FigJamNode>;
  seen: WeakSet<object>;
};

type LineRange = {
  start: number;
  end: number;
};

const TEXT_STYLE_FIELDS = [
  "fontName",
  "fontStyle",
  "fontWeight",
  "textDecoration",
  "hyperlink",
  "listOptions",
  "indentation",
];

window.__figjam2mdReadFigJamAsMarkdown = readFigJamAsMarkdown;
window.__figjam2mdProbe = probeFigJam;

if (!window.__figjam2mdBridgeLoaded) {
  window.__figjam2mdBridgeLoaded = true;

  window.addEventListener("message", (event: MessageEvent<unknown>) => {
    if (event.source !== window || !isContentRequest(event.data)) {
      return;
    }

    void respondToContentRequest(event.data);
  });
}

async function respondToContentRequest(request: Required<ContentRequest>) {
  try {
    const result = await readFigJamAsMarkdown();
    window.postMessage(
      {
        source: "figjam2md-bridge",
        type: "FIGJAM2MD_RESPONSE",
        id: request.id,
        ok: true,
        ...result,
      },
      "*",
    );
  } catch (error) {
    window.postMessage(
      {
        source: "figjam2md-bridge",
        type: "FIGJAM2MD_RESPONSE",
        id: request.id,
        ok: false,
        error: error instanceof Error ? error.message : "Unable to read FigJam content.",
      },
      "*",
    );
  }
}

function isContentRequest(value: unknown): value is Required<ContentRequest> {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as ContentRequest).source === "figjam2md-content" &&
    (value as ContentRequest).type === "FIGJAM2MD_REQUEST" &&
    typeof (value as ContentRequest).id === "string"
  );
}

function probeFigJam(): FigJamProbe {
  const figma = window.figma as FigmaLike | undefined;
  const page = isObject(figma) ? figma.currentPage : undefined;
  const selection = page ? arrayFromNodes(page.selection) : [];
  const children = page ? arrayFromNodes(page.children) : [];

  return {
    href: window.location.href,
    hasFigma: isObject(figma),
    hasCurrentPage: isObject(page),
    ...(typeof figma?.editorType === "string" ? { editorType: figma.editorType } : {}),
    ...(page?.name ? { pageName: page.name } : {}),
    ...(page ? { selectionCount: selection.length, childCount: children.length } : {}),
  };
}

async function readFigJamAsMarkdown(): Promise<MarkdownDocument> {
  const figma = window.figma as FigmaLike | undefined;
  if (!isObject(figma)) {
    throw new Error("window.figma is not available in this frame. Open a fully loaded FigJam file and try again.");
  }

  if (figma.editorType && figma.editorType !== "figjam") {
    throw new Error("This extension only reads FigJam files. Open a FigJam board and try again.");
  }

  const page = figma.currentPage;
  if (!page) {
    throw new Error("window.figma exists, but currentPage is not available yet. Wait for the FigJam board to finish loading, then click Refresh.");
  }

  // Do not call PageNode.loadAsync() here. In the FigJam web page context
  // `window.figma.currentPage` is already the live page object, and awaiting
  // loadAsync() can hang outside a normal plugin runtime.
  const pageChildren = arrayFromNodes(page.children).filter(isVisibleNode);
  const rawSelection = arrayFromNodes(page.selection).filter(isVisibleNode);
  const selection = removeDescendants(rawSelection);
  const roots = canvasSort(selection.length > 0 ? selection : pageChildren);
  const scope: "selection" | "page" = selection.length > 0 ? "selection" : "page";

  if (roots.length === 0) {
    throw new Error(scope === "selection" ? "The current selection is empty." : "This FigJam page has no readable items.");
  }

  const context: ConversionContext = {
    nodeById: indexNodes(pageChildren),
    seen: new WeakSet<object>(),
  };

  const blocks = roots.map((node) => nodeToMarkdown(node, 2, context)).filter(Boolean);
  const pageName = cleanText(page.name || "");
  const title = scope === "page" && pageName ? heading(pageName, 1) : "";
  const markdown = joinBlocks([title, ...blocks]);

  if (!markdown) {
    throw new Error("No readable text was found in the selected FigJam content.");
  }

  return {
    markdown,
    itemCount: roots.length,
    scope,
    ...(pageName ? { pageName } : {}),
  };
}

function nodeToMarkdown(node: FigJamNode, depth: number, context: ConversionContext): string {
  if (!isObject(node) || context.seen.has(node) || !isVisibleNode(node)) {
    return "";
  }
  context.seen.add(node);

  const type = nodeType(node);
  const label = shouldShowLabel(node) ? readableName(node) : "";

  if (type === "TABLE") {
    return withLabel(label, depth, tableToMarkdown(node), "heading");
  }

  if (type === "CODE_BLOCK") {
    const code = cleanText(stringProperty(node, "code") || textForNode(node));
    return withLabel(label, depth, code ? fencedCode(code, node) : "", "bold");
  }

  if (type === "CONNECTOR") {
    return connectorToMarkdown(node, context) || label;
  }

  const text = textForNode(node);
  const children = childBlocks(node, depth + 1, context);

  if (isContainerType(type)) {
    const title = label ? heading(label, depth) : "";
    return joinBlocks([title, text, ...children]);
  }

  if (type === "STICKY") {
    return stickyToMarkdown(node, label, text, children);
  }

  if (text && label && plainMarkdown(text) !== label) {
    return joinBlocks([bold(label), text, ...children]);
  }

  return joinBlocks([text || label, ...children]);
}

function childBlocks(node: FigJamNode, depth: number, context: ConversionContext): string[] {
  return canvasSort(arrayFromNodes(node.children).filter(isVisibleNode))
    .map((child) => nodeToMarkdown(child, depth, context))
    .filter(Boolean);
}

function textForNode(node: FigJamNode): string {
  const type = nodeType(node);

  if (type === "CODE_BLOCK") {
    return cleanText(stringProperty(node, "code"));
  }

  const textSublayer = property(node, "text");
  if (isObject(textSublayer)) {
    const text = richTextToMarkdown(textSublayer as TextLike);
    if (text) {
      return text;
    }
  }

  if (typeof node.characters === "string") {
    return richTextToMarkdown(node as TextLike);
  }

  return firstText([
    property(node, "plainText"),
    property(node, "content"),
    property(node, "contents"),
    property(node, "value"),
    property(node, "label"),
    property(node, "title"),
    property(node, "description"),
  ]);
}

function plainTextForNode(node: FigJamNode): string {
  const textSublayer = property(node, "text");
  if (isObject(textSublayer)) {
    const text = charactersOf(textSublayer as TextLike);
    if (text) {
      return cleanText(text);
    }
  }

  if (typeof node.characters === "string") {
    return cleanText(node.characters);
  }

  return plainMarkdown(textForNode(node));
}

function richTextToMarkdown(textNode: TextLike): string {
  const characters = charactersOf(textNode);
  if (!characters.trim()) {
    return "";
  }

  const segments = styledTextSegments(textNode, characters.length);
  if (segments.length === 0) {
    return cleanText(characters);
  }

  const lines = splitLineRanges(characters)
    .map((range) => lineRangeToMarkdown(characters, range, segments))
    .join("\n");

  return cleanText(lines);
}

function styledTextSegments(textNode: TextLike, fallbackEnd: number): StyledTextSegmentLike[] {
  const getter = property(textNode, "getStyledTextSegments");
  if (typeof getter !== "function") {
    return [];
  }

  try {
    const segments = getter.call(textNode, TEXT_STYLE_FIELDS);
    if (!Array.isArray(segments)) {
      return [];
    }

    return segments.filter(isObject).map((segment, index) => ({
      ...segment,
      start: toInteger(property(segment, "start") ?? (index === 0 ? 0 : undefined)),
      end: toInteger(property(segment, "end") ?? fallbackEnd),
    }));
  } catch {
    return [];
  }
}

function lineRangeToMarkdown(text: string, range: LineRange, segments: StyledTextSegmentLike[]): string {
  const rawLine = text.slice(range.start, range.end);
  if (!rawLine.trim()) {
    return "";
  }

  const list = listInfoForLine(text, range, segments);
  const formatted = segmentsForRange(range, segments)
    .map(({ segment, start, end }) => formatInlineText(text.slice(start, end), segment))
    .join("");

  if (list) {
    return `${"  ".repeat(list.indent)}${list.marker} ${formatted.trimStart()}`;
  }

  return escapeMarkdownLineStart(formatted);
}

function segmentsForRange(
  range: LineRange,
  segments: StyledTextSegmentLike[],
): Array<{ segment: StyledTextSegmentLike; start: number; end: number }> {
  return segments
    .map((segment) => {
      const start = Math.max(toInteger(segment.start), range.start);
      const end = Math.min(toInteger(segment.end), range.end);
      return { segment, start, end };
    })
    .filter(({ start, end }) => end > start);
}

function formatInlineText(text: string, segment: StyledTextSegmentLike): string {
  if (!text) {
    return "";
  }

  const match = /^(\s*)([\s\S]*?)(\s*)$/.exec(text);
  const leading = match?.[1] || "";
  const body = match?.[2] || "";
  const trailing = match?.[3] || "";

  if (!body) {
    return text;
  }

  let formatted = escapeInlineMarkdown(body);
  const boldText = isBoldSegment(segment);
  const italicText = isItalicSegment(segment);
  const strikeText = String(segment.textDecoration || "").toUpperCase() === "STRIKETHROUGH";

  if (boldText) {
    formatted = `**${formatted}**`;
  }
  if (italicText) {
    formatted = `_${formatted}_`;
  }
  if (strikeText) {
    formatted = `~~${formatted}~~`;
  }

  const href = hyperlinkUrl(segment.hyperlink);
  if (href) {
    formatted = `[${formatted}](${escapeUrl(href)})`;
  }

  return `${leading}${formatted}${trailing}`;
}

function isBoldSegment(segment: StyledTextSegmentLike): boolean {
  const weight = toNumber(segment.fontWeight);
  if (weight >= 600) {
    return true;
  }

  const style = `${stringProperty(segment, "fontStyle")} ${fontNameStyle(segment.fontName)}`.toLowerCase();
  return /\b(bold|semibold|demibold|black|heavy|extrabold|extra bold)\b/.test(style);
}

function isItalicSegment(segment: StyledTextSegmentLike): boolean {
  const style = `${stringProperty(segment, "fontStyle")} ${fontNameStyle(segment.fontName)}`.toLowerCase();
  return /\bitalic\b/.test(style);
}

function fontNameStyle(value: unknown): string {
  return isObject(value) ? stringProperty(value, "style") : "";
}

function hyperlinkUrl(value: unknown): string {
  if (typeof value === "string") {
    return /^https?:\/\//i.test(value) || /^mailto:/i.test(value) ? value : "";
  }

  if (!isObject(value)) {
    return "";
  }

  const type = stringProperty(value, "type").toUpperCase();
  const url = stringProperty(value, "url") || stringProperty(value, "href");
  if (url && (type === "URL" || /^https?:\/\//i.test(url) || /^mailto:/i.test(url))) {
    return url;
  }

  return "";
}

function listInfoForLine(
  text: string,
  range: LineRange,
  segments: StyledTextSegmentLike[],
): { marker: "-" | "1."; indent: number } | null {
  const line = text.slice(range.start, range.end);
  const firstNonWhitespace = line.search(/\S/);
  if (firstNonWhitespace === -1) {
    return null;
  }

  const index = range.start + firstNonWhitespace;
  const segment = segments.find((candidate) => toInteger(candidate.start) <= index && index < toInteger(candidate.end));
  if (!segment) {
    return null;
  }

  const options = segment.listOptions;
  if (!isObject(options)) {
    return null;
  }

  const type = (stringProperty(options, "type") || stringProperty(options, "listType")).toUpperCase();
  if (type !== "ORDERED" && type !== "UNORDERED") {
    return null;
  }

  const rawIndent = toInteger(segment.indentation);
  return {
    marker: type === "ORDERED" ? "1." : "-",
    indent: Math.max(0, rawIndent - 1),
  };
}

function splitLineRanges(text: string): LineRange[] {
  const ranges: LineRange[] = [];
  let start = 0;

  for (let index = 0; index < text.length; index += 1) {
    if (text[index] === "\n") {
      ranges.push({ start, end: index });
      start = index + 1;
    }
  }

  ranges.push({ start, end: text.length });
  return ranges;
}

function tableToMarkdown(node: FigJamNode): string {
  const rows = toInteger(node.numRows ?? property(node, "rowCount") ?? property(node, "rows"));
  const columns = toInteger(node.numColumns ?? property(node, "columnCount") ?? property(node, "columns"));

  if (rows <= 0 || columns <= 0) {
    return "";
  }

  const matrix: string[][] = [];
  for (let row = 0; row < rows; row += 1) {
    const cells: string[] = [];
    for (let column = 0; column < columns; column += 1) {
      cells.push(escapeTableCell(readTableCell(node, row, column)));
    }
    matrix.push(cells);
  }

  if (matrix.every((row) => row.every((cell) => !cell.trim()))) {
    return "";
  }

  const header = matrix[0] || [];
  const separator = header.map(() => "---");
  const body = matrix.slice(1);

  return [header, separator, ...body].map((row) => `| ${row.join(" | ")} |`).join("\n");
}

function readTableCell(node: FigJamNode, row: number, column: number): string {
  if (typeof node.cellAt === "function") {
    try {
      const cell = node.cellAt(row, column);
      return isObject(cell) ? textForNode(cell as FigJamNode) : "";
    } catch {
      return "";
    }
  }

  const cells = arrayFromNodes(node.children);
  const match = cells.find((cell) => {
    const rowIndex = toInteger(property(cell, "rowIndex") ?? property(cell, "row"));
    const columnIndex = toInteger(property(cell, "columnIndex") ?? property(cell, "column"));
    return rowIndex === row && columnIndex === column;
  });

  return match ? textForNode(match) : "";
}

function connectorToMarkdown(node: FigJamNode, context: ConversionContext): string {
  const text = textForNode(node);
  const label = shouldShowLabel(node) ? readableName(node) : "";
  const start = endpointLabel(property(node, "connectorStart"), context);
  const end = endpointLabel(property(node, "connectorEnd"), context);

  if (start || end) {
    const arrow = connectorArrow(node);
    const summary = `${start || "?"} ${arrow} ${end || "?"}`;
    return text ? `${summary}: ${text}` : summary;
  }

  return text || label;
}

function endpointLabel(endpoint: unknown, context: ConversionContext): string {
  if (!isObject(endpoint)) {
    return "";
  }

  const id = stringProperty(endpoint, "endpointNodeId");
  const node = id ? context.nodeById.get(id) : undefined;
  if (!node) {
    return "";
  }

  return firstLine(plainTextForNode(node) || readableName(node), 80);
}

function connectorArrow(node: FigJamNode): string {
  const startCap = stringProperty(node, "connectorStartStrokeCap").toUpperCase();
  const endCap = stringProperty(node, "connectorEndStrokeCap").toUpperCase();
  const startArrow = startCap !== "" && startCap !== "NONE";
  const endArrow = endCap !== "" && endCap !== "NONE";

  if (startArrow && endArrow) {
    return "↔";
  }
  if (startArrow && !endArrow) {
    return "←";
  }
  if (!startArrow && !endArrow) {
    return "—";
  }
  return "→";
}

function stickyToMarkdown(node: FigJamNode, label: string, text: string, children: string[]): string {
  const authorVisible = property(node, "authorVisible") === true;
  const author = authorVisible ? cleanText(stringProperty(node, "authorName")) : "";
  const content = author && text ? `${text}\n\n— ${author}` : text;

  if (content && label && plainMarkdown(content) !== label) {
    return joinBlocks([bold(label), content, ...children]);
  }

  return joinBlocks([content || label, ...children]);
}

function withLabel(label: string, depth: number, content: string, mode: "bold" | "heading"): string {
  if (!label) {
    return content;
  }

  return joinBlocks([mode === "heading" ? heading(label, depth) : bold(label), content]);
}

type CanvasSortItem = {
  node: FigJamNode;
  index: number;
  bounds: CanvasBounds;
};

type CanvasRow = {
  items: CanvasSortItem[];
  top: number;
  bottom: number;
};

type CanvasBounds = {
  left: number;
  top: number;
  right: number;
  bottom: number;
  width: number;
  height: number;
};

function canvasSort(nodes: FigJamNode[]): FigJamNode[] {
  if (nodes.length <= 1) {
    return nodes.slice();
  }

  const items = nodes.map((node, index) => ({ node, index, bounds: canvasBounds(node) }));
  const rowTolerance = canvasRowTolerance(items);
  const rows: CanvasRow[] = [];

  for (const item of items.slice().sort(compareCanvasTopThenLeft)) {
    const row = rows.find((candidate) => belongsInCanvasRow(candidate, item, rowTolerance));
    if (row) {
      row.items.push(item);
      row.top = Math.min(row.top, item.bounds.top);
      row.bottom = Math.max(row.bottom, item.bounds.bottom);
    } else {
      rows.push({ items: [item], top: item.bounds.top, bottom: item.bounds.bottom });
    }
  }

  return rows
    .sort(compareCanvasRows)
    .flatMap((row) => row.items.sort(compareCanvasLeftThenTop))
    .map((item) => item.node);
}

function compareCanvasTopThenLeft(a: CanvasSortItem, b: CanvasSortItem): number {
  return (
    a.bounds.top - b.bounds.top ||
    a.bounds.left - b.bounds.left ||
    a.bounds.bottom - b.bounds.bottom ||
    a.bounds.right - b.bounds.right ||
    a.index - b.index
  );
}

function compareCanvasLeftThenTop(a: CanvasSortItem, b: CanvasSortItem): number {
  return (
    a.bounds.left - b.bounds.left ||
