function canvasBounds(node: FigJamNode): CanvasBounds {
  const left = toNumber(node.absoluteBoundingBox?.x ?? node.x);
  const top = toNumber(node.absoluteBoundingBox?.y ?? node.y);
  const width = Math.max(0, toNumber(node.absoluteBoundingBox?.width ?? node.width));
  const height = Math.max(0, toNumber(node.absoluteBoundingBox?.height ?? node.height));

