async function readFigJamHtmlAsMarkdown(figma: FigmaLike): Promise<MarkdownDocument | null> {
  if (typeof figma.getHTMLString !== "function") {
    return null;
  }

  const html = await Promise.resolve(figma.getHTMLString.call(figma));
  if (typeof html !== "string" || !html.trim()) {
    return null;
  }

  const markdown = htmlToMarkdown(html);
  if (!markdown) {
    return null;
  }

  return {
    markdown,
    itemCount: Math.max(1, countHtmlBlocks(html)),
    scope: "selection",
  };
}

function htmlToMarkdown(html: string): string {
  const document = new DOMParser().parseFromString(html, "text/html");
  const root = document.body || document.documentElement;
  const blocks = htmlChildrenInCanvasOrder(root)
    .map((child) => htmlNodeToMarkdown(child, { listDepth: 0 }))
    .filter(Boolean);

  return joinBlocks(blocks.length > 0 ? blocks : [htmlInlineChildrenToMarkdown(root)]);
}

type HtmlContext = {
  listDepth: number;
  listType?: "ul" | "ol";
};

function htmlNodeToMarkdown(node: Node, context: HtmlContext): string {
  if (node.nodeType === Node.TEXT_NODE) {
    return cleanInlineWhitespace(node.textContent || "");
  }

  if (!(node instanceof Element)) {
    return "";
  }

  const tag = node.tagName.toLowerCase();
  if (tag === "script" || tag === "style" || tag === "svg") {
    return "";
  }

  if (tag === "br") {
    return "\n";
  }

  if (/^h[1-6]$/.test(tag)) {
    return heading(htmlInlineChildrenToMarkdown(node), Number(tag.slice(1)));
  }

  if (tag === "p" || tag === "section" || tag === "article" || tag === "main" || tag === "header" || tag === "footer") {
    return htmlInlineOrBlockChildrenToMarkdown(node, context);
  }

  if (tag === "div") {
    return htmlInlineOrBlockChildrenToMarkdown(node, context);
  }

  if (tag === "ul" || tag === "ol") {
    return htmlChildrenInCanvasOrder(node)
      .map((child) => htmlNodeToMarkdown(child, { listDepth: context.listDepth, listType: tag as "ul" | "ol" }))
      .filter(Boolean)
      .join("\n");
  }

  if (tag === "li") {
    const marker = context.listType === "ol" ? "1." : "-";
    const prefix = `${"  ".repeat(context.listDepth)}${marker} `;
    const content = htmlInlineOrBlockChildrenToMarkdown(node, { ...context, listDepth: context.listDepth + 1 });
    return prefix + content.replace(/\n/g, `\n${"  ".repeat(context.listDepth + 1)}`);
  }

  if (tag === "blockquote") {
    return htmlInlineOrBlockChildrenToMarkdown(node, context)
      .split("\n")
      .map((line) => `> ${line}`)
      .join("\n");
  }

  if (tag === "pre") {
    const code = cleanText(node.textContent || "");
    return code ? fencedCode(code, {} as FigJamNode) : "";
  }

  if (tag === "table") {
    return htmlTableToMarkdown(node);
  }

  if (isInlineHtmlTag(tag)) {
    return htmlInlineNodeToMarkdown(node, context);
  }

  return htmlInlineOrBlockChildrenToMarkdown(node, context);
}

function htmlInlineOrBlockChildrenToMarkdown(element: Element, context: HtmlContext): string {
  const children = htmlChildrenInCanvasOrder(element);
  const hasBlockChildren = children.some((child) => child instanceof Element && isBlockHtmlTag(child.tagName.toLowerCase()));

  if (!hasBlockChildren) {
    return htmlInlineChildrenToMarkdown(element);
  }

  return joinBlocks(children.map((child) => htmlNodeToMarkdown(child, context)).filter(Boolean));
}

function htmlInlineChildrenToMarkdown(parent: ParentNode): string {
  return cleanText(
    Array.from(parent.childNodes)
      .map((child) => htmlInlineNodeToMarkdown(child, { listDepth: 0 }))
      .join(""),
  );
}

function htmlInlineNodeToMarkdown(node: Node, context: HtmlContext): string {
  if (node.nodeType === Node.TEXT_NODE) {
    return cleanInlineWhitespace(node.textContent || "");
  }

  if (!(node instanceof Element)) {
    return "";
  }

  const tag = node.tagName.toLowerCase();
  if (tag === "br") {
    return "\n";
