declare global {
  interface Window {
    __figjam2mdContentLoaded?: boolean;
    __figjam2mdContentFrameRead?: () => Promise<MarkdownResult>;
  }
}

type BridgeResponse = {
  source: "figjam2md-bridge";
  type: "FIGJAM2MD_RESPONSE";
  id: string;
  ok: boolean;
  markdown?: string;
  itemCount?: number;
  scope?: "selection" | "page";
  pageName?: string;
  error?: string;
};

type MarkdownResult = {
  markdown: string;
  itemCount: number;
  scope: "selection" | "page";
  pageName?: string;
};

if (!window.__figjam2mdContentLoaded) {
  window.__figjam2mdContentLoaded = true;

  const APP_ID = "figjam2md-dialog-root";
  const BRIDGE_ID = "figjam2md-page-bridge";
  const isTopFrame = window.top === window;

  window.__figjam2mdContentFrameRead = requestMarkdownFromPageBridge;

  let host: HTMLDivElement | null = null;
  let shadow: ShadowRoot | null = null;
  let textarea: HTMLTextAreaElement | null = null;
  let status: HTMLDivElement | null = null;
  let copyButton: HTMLButtonElement | null = null;

  chrome.runtime.onMessage.addListener((message) => {
    if (isTopFrame && message?.type === "FIGJAM2MD_TOGGLE") {
      void toggleDialog();
    }
