function connectorToMermaidBlock(node: FigJamNode, start: string, end: string, label: string): string {
  const edge = mermaidConnectorEdge(node);
  const edgeLabel = label ? `|${mermaidEdgeLabel(label)}|` : "";
  const link = `${edge.operator}${edgeLabel}`;
  const from = edge.reverse ? "B" : "A";
  const to = edge.reverse ? "A" : "B";

  return [
    "```mermaid",
    "flowchart LR",
    `  A["${mermaidLabel(start)}"]`,
    `  B["${mermaidLabel(end)}"]`,
    `  ${from} ${link} ${to}`,
    "```",
  ].join("\n");
}

function mermaidConnectorEdge(node: FigJamNode): { operator: "-->" | "---" | "<-->"; reverse: boolean } {
  const startArrow = hasArrowCap(stringProperty(node, "connectorStartStrokeCap"));
  const endArrow = hasArrowCap(stringProperty(node, "connectorEndStrokeCap"));

  if (startArrow && endArrow) {
    return { operator: "<-->", reverse: false };
  }
  if (startArrow && !endArrow) {
    return { operator: "-->", reverse: true };
  }
  if (!startArrow && !endArrow) {
    return { operator: "---", reverse: false };
  }
  return { operator: "-->", reverse: false };
}

function hasArrowCap(value: string): boolean {
  const cap = value.toUpperCase();
  return cap !== "" && cap !== "NONE";
}

function mermaidLabel(value: string): string {
  return cleanText(value)
    .replaceAll("&", "&amp;")
    .replaceAll("\"", "&quot;")
    .replaceAll("[", "&#91;")
    .replaceAll("]", "&#93;")
    .replaceAll("|", "&#124;")
    .replace(/\n+/g, "<br/>");
}

function mermaidEdgeLabel(value: string): string {
  return mermaidLabel(value).replaceAll("`", "&#96;");
}

