function collectConnectorNodes(nodes: FigJamNode[]): FigJamNode[] {
  const connectors: FigJamNode[] = [];
  const seen = new WeakSet<object>();

  const visit = (node: FigJamNode) => {
    if (!isObject(node) || seen.has(node) || !isVisibleNode(node)) {
      return;
    }
    seen.add(node);

    if (nodeType(node) === "CONNECTOR") {
      connectors.push(node);
      return;
    }

    for (const child of arrayFromNodes(node.children)) {
      visit(child);
    }
  };

  nodes.forEach(visit);
  return canvasSort(connectors);
}

function connectorsToMermaidBlock(connectors: FigJamNode[], context: ConversionContext): string {
  const edges = connectors
    .map((connector, index) => connectorToMermaidEdge(connector, context, index))
    .filter((edge): edge is MermaidEdge => Boolean(edge));

  if (edges.length === 0) {
    return "";
  }

  const endpointIds = new Map<string, string>();
  const endpointLines: string[] = [];
  const idForEndpoint = (endpoint: MermaidEndpoint) => {
    const existing = endpointIds.get(endpoint.key);
    if (existing) {
      return existing;
    }

    const id = `N${endpointIds.size + 1}`;
    endpointIds.set(endpoint.key, id);
    endpointLines.push(`  ${id}["${mermaidLabel(endpoint.label)}"]`);
    return id;
  };

  const edgeLines = edges.map((edge) => {
    const fromId = idForEndpoint(edge.from);
    const toId = idForEndpoint(edge.to);
    const edgeLabel = edge.label ? `|${mermaidEdgeLabel(edge.label)}|` : "";
    return `  ${fromId} ${edge.operator}${edgeLabel} ${toId}`;
  });

  return ["```mermaid", "flowchart LR", ...endpointLines, ...edgeLines, "```"].join("\n");
}

function connectorToMermaidEdge(connector: FigJamNode, context: ConversionContext, index: number): MermaidEdge | null {
  const start = endpointInfo(property(connector, "connectorStart"), context, `connector-${index}-start`, "Unknown start");
  const end = endpointInfo(property(connector, "connectorEnd"), context, `connector-${index}-end`, "Unknown end");
  if (!start && !end) {
    return null;
  }

  const edge = mermaidConnectorEdge(connector);
  const from = edge.reverse ? end || unknownEndpoint(index, "end") : start || unknownEndpoint(index, "start");
  const to = edge.reverse ? start || unknownEndpoint(index, "start") : end || unknownEndpoint(index, "end");
  const label = textForNode(connector) || (shouldShowLabel(connector) ? readableName(connector) : "");

  return {
    from,
    to,
    operator: edge.operator,
    label,
  };
}

function endpointInfo(endpoint: unknown, context: ConversionContext, fallbackKey: string, fallbackLabel: string): MermaidEndpoint | null {
  if (!isObject(endpoint)) {
    return null;
  }

  const id = stringProperty(endpoint, "endpointNodeId");
  const node = id ? context.nodeById.get(id) : undefined;
  if (node) {
    return {
      key: `node:${id}`,
      label: firstLine(plainTextForNode(node) || readableName(node) || fallbackLabel, 80),
    };
  }

  const position = property(endpoint, "position");
  if (isObject(position)) {
    const x = Math.round(toNumber(property(position, "x")));
    const y = Math.round(toNumber(property(position, "y")));
    return {
      key: `point:${x},${y}`,
      label: fallbackLabel,
    };
  }

  return id ? { key: `missing:${id}`, label: fallbackLabel } : { key: fallbackKey, label: fallbackLabel };
}

function unknownEndpoint(index: number, side: "start" | "end"): MermaidEndpoint {
  return {
    key: `connector-${index}-${side}`,
    label: side === "start" ? "Unknown start" : "Unknown end",
  };
}

function connectorFallbackText(node: FigJamNode): string {
  const hasStart = isObject(property(node, "connectorStart"));
  const hasEnd = isObject(property(node, "connectorEnd"));
  if (hasStart || hasEnd) {
    return "";
  }

  return textForNode(node) || (shouldShowLabel(node) ? readableName(node) : "");
}

