function withLabel(label: string, depth: number, content: string, mode: "bold" | "heading"): string {
  if (!label) {
    return content;
  }

  return joinBlocks([mode === "heading" ? heading(label, depth) : bold(label), content]);
}

function isAutoGeneratedLabel(node: FigJamNode, label: string): boolean {
  const normalizedLabel = normalizeComparableText(label);
  if (!normalizedLabel) {
    return false;
  }

  const descendantText = normalizeComparableText(descendantPlainText(node, new WeakSet<object>()));
  return Boolean(descendantText && descendantText === normalizedLabel);
}

function descendantPlainText(node: FigJamNode, seen: WeakSet<object>): string {
  if (!isObject(node) || seen.has(node)) {
    return "";
  }
  seen.add(node);

  return arrayFromNodes(node.children)
    .filter((child) => isVisibleNode(child) && nodeType(child) !== "CONNECTOR")
    .map((child) => joinBlocks([ownPlainText(child), descendantPlainText(child, seen)]))
    .filter(Boolean)
    .join("\n");
}

function ownPlainText(node: FigJamNode): string {
  const type = nodeType(node);
  if (type === "SECTION" || type === "FRAME" || type === "GROUP") {
    return "";
  }
  return plainTextForNode(node);
}

function normalizeComparableText(value: string): string {
  return cleanText(value).replace(/\s+/g, " ").trim().toLowerCase();
}

